def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_defects = 0
    my_defects = 0
    for i in range(n):
        me, op = history[i]
        if op == 'D':
            opp_defects += 1
        if me == 'D':
            my_defects += 1

    opp_coops = n - opp_defects

    if opp_coops == 0 and n >= 5:
        return 'D'

    streak_d = 0
    for i in range(n-1, -1, -1):
        if history[i][1] == 'D':
            streak_d += 1
        else:
            break

    if streak_d >= 6:
        return 'D'

    defect_rate = opp_defects / n
    last_me, last_op = history[-1]

    if last_op == 'D':
        if defect_rate > 0.6:
            if rng.random() < 0.05:
                return 'C'
            return 'D'
        else:
            if rng.random() < 0.25:
                return 'C'
            return 'D'

    if last_op == 'C':
        if defect_rate < 0.3:
            return 'C'
        if rng.random() < 0.85:
            return 'C'
        return 'D'

    return 'C'
